+std::set<PlaneLinel> Compressor::getLinelsBetween_(
+        const PlanePoint& ini,
+        const PlanePoint& end) {
+    std::set<PlaneLinel> result;
+    for (Axis d = 0; d < 2; d++) {
+        Axis d1 = (d + 1) % 2;
+        if (ini[d] == end[d]) {
+            PlaneLinel linel;
+            linel.first[d] = ini[d];
+            linel.second = d1;
+            for (CellDir
+                 k = std::min(ini[d1], end[d1]);
+                 k < std::max(ini[d1], end[d1]); k++) {
+                linel.first[d1] = k;
+                result.insert(linel);
+            }
+        }
+    }
+    return result;
+}
