+        const auto face = tools.getCellFaceAxis(coordinate);
+        if (face.first) {
+            owned.faces[{cell, face.second}].insert(id);
+            continue;
+        }
+        owned.interiors[cell].insert(id);
+    }
+    return owned;
+}
