+    
+    CoordinateId c0 = findOrAddCoord(mesh, v0);
+    CoordinateId c1 = findOrAddCoord(mesh, v1);
+    
+    mesh.groups[groupId].elements.push_back(Element({c0, c1}, Element::Type::Line));
+}
